const r = $json;
const out = (r.stdout || '').trim();
const err = (r.stderr || '').trim();

const counts = {};
for (const line of out.split('\n')) {
  const m = line.match(/^\s*(\S+)\s+(\d+)\s+行\s*$/);
  if (m) counts[m[1]] = Number(m[2]);
}

if (r.code !== 0) {
  throw new Error('同步配置失败：' + (err.split('\n').slice(-4).join(' | ') || out));
}

return [{
  json: {
    ok: true,
    counts,
    stdout: out
  }
}];

const r = $json;
const out = (r.stdout || '').trim();
const err = (r.stderr || '').trim();

if (r.code !== 0) {
  throw new Error('生成计算表失败：' + (err.split('\n').slice(-6).join(' | ')));
}

const line = out.split('\n').find(l => l.startsWith('RESULT '));
const result = line ? JSON.parse(line.slice(7)) : { ok: false };

return [{
  json: {
    ...result,
    ok: Boolean(result.ok),
    summary: out.split('\n').filter(l => l.includes('汇总') || l.includes('明细')).join(' / '),
    log: out
  }
}];
